class Solution {
public:
    string largestMultipleOfThree(vector<int>& digits) {
        vector<int> cnt(10, 0);
        int sum = 0;
        for (int x : digits) ++cnt[x], sum += x;
        auto remove = [&](int rem, int need) {
            for (int d = 0; d <= 9 && need; ++d)
                if (d % 3 == rem) {
                    int take = min(need, cnt[d]);
                    cnt[d] -= take;
                    need -= take;
                }
            return need == 0;
        };
        if (sum % 3 == 1) {
            vector<int> backup = cnt;
            if (!remove(1, 1)) { cnt = backup; remove(2, 2); }
        } else if (sum % 3 == 2) {
            vector<int> backup = cnt;
            if (!remove(2, 1)) { cnt = backup; remove(1, 2); }
        }
        string ans;
        for (int d = 9; d >= 0; --d) ans.append(cnt[d], char('0' + d));
        if (!ans.empty() && ans[0] == '0') return "0";
        return ans;
    }
};
